div.script:

document.getElementById('backToHubBtn').href = 'https://cdn.jsdelivr.net/gh/mathbuddies/leawoodmiddle@main/index.svg?v=' + Date.now();

const defaultDecks = {
  "Leawood Middle": [
    { front: "What is the mascot of Leawood Middle?", back: "The Eagles! 🦅", mastered: false },
    { front: "What year does Buc-ee's come to KC near Speedway/Legends?", back: "Late 2027!", mastered: false }
  ],
  "General Knowledge": [
    { front: "What is photosynthesis?", back: "The process plants use to convert light into energy.", mastered: false },
    { front: "What is the powerhouse of the cell?", back: "Mitochondria!", mastered: false }
  ]
};

let decks = JSON.parse(localStorage.getItem('pro_flashcards_decks') || JSON.stringify(defaultDecks));
let currentDeckKey = Object.keys(decks)[0] || "Leawood Middle";
let currentIndex = 0;
let isFlipped = false;

function saveStorage() {
  localStorage.setItem('pro_flashcards_decks', JSON.stringify(decks));
}

function populateDeckSelect() {
  const select = document.getElementById('deckSelect');
  select.innerHTML = '';
  Object.keys(decks).forEach(key => {
    const opt = document.createElement('option');
    opt.value = key;
    opt.textContent = key;
    if (key === currentDeckKey) opt.selected = true;
    select.appendChild(opt);
  });
}

function switchDeck() {
  currentDeckKey = document.getElementById('deckSelect').value;
  currentIndex = 0;
  isFlipped = false;
  renderCard();
}

function renderCard() {
  const cardEl = document.getElementById('activeFlashcard');
  cardEl.classList.remove('flipped');
  isFlipped = false;

  const deck = decks[currentDeckKey] || [];
  const progressEl = document.getElementById('deckProgress');
  const frontEl = document.getElementById('cardFrontText');
  const backEl = document.getElementById('cardBackText');
  const masteredCountEl = document.getElementById('masteredCount');
  const remainingCountEl = document.getElementById('remainingCount');

  if (deck.length === 0) {
    progressEl.textContent = "Card 0 of 0";
    frontEl.textContent = 'No cards in this deck yet! Click "+ Add Card" above to add one.';
    backEl.textContent = 'Answer will show here.';
    masteredCountEl.textContent = '0';
    remainingCountEl.textContent = '0';
    return;
  }

  if (currentIndex >= deck.length) currentIndex = 0;
  if (currentIndex < 0) currentIndex = deck.length - 1;

  const card = deck[currentIndex];
  progressEl.textContent = `Card ${currentIndex + 1} of ${deck.length}`;
  frontEl.textContent = card.front;
  backEl.textContent = card.back;

  const mastered = deck.filter(c => c.mastered).length;
  masteredCountEl.textContent = mastered;
  remainingCountEl.textContent = deck.length - mastered;
}

function flipCard() {
  const deck = decks[currentDeckKey] || [];
  if (deck.length === 0) return;
  const cardEl = document.getElementById('activeFlashcard');
  isFlipped = !isFlipped;
  if (isFlipped) cardEl.classList.add('flipped');
  else cardEl.classList.remove('flipped');
}

function nextCard() {
  const deck = decks[currentDeckKey] || [];
  if (deck.length === 0) return;
  currentIndex = (currentIndex + 1) % deck.length;
  renderCard();
}

function prevCard() {
  const deck = decks[currentDeckKey] || [];
  if (deck.length === 0) return;
  currentIndex = (currentIndex - 1 + deck.length) % deck.length;
  renderCard();
}

function markMastered() {
  const deck = decks[currentDeckKey] || [];
  if (deck.length === 0) return;
  deck[currentIndex].mastered = true;
  saveStorage();
  nextCard();
}

function deleteCurrentCard() {
  const deck = decks[currentDeckKey] || [];
  if (deck.length === 0) return;
  deck.splice(currentIndex, 1);
  saveStorage();
  if (currentIndex >= deck.length && currentIndex > 0) currentIndex--;
  renderCard();
}

function openAddCardModal() {
  document.getElementById('newFrontInput').value = '';
  document.getElementById('newBackInput').value = '';
  document.getElementById('addCardModal').classList.add('open');
}

function saveNewCard() {
  const front = document.getElementById('newFrontInput').value.trim();
  const back = document.getElementById('newBackInput').value.trim();
  if (front && back) {
    if (!decks[currentDeckKey]) decks[currentDeckKey] = [];
    decks[currentDeckKey].push({ front: front, back: back, mastered: false });
    saveStorage();
    currentIndex = decks[currentDeckKey].length - 1;
    renderCard();
    closeModal('addCardModal');
  } else {
    alert('Please fill out both Question and Answer fields.');
  }
}

function openNewDeckModal() {
  document.getElementById('newDeckNameInput').value = '';
  document.getElementById('newDeckModal').classList.add('open');
}

function saveNewDeck() {
  const name = document.getElementById('newDeckNameInput').value.trim();
  if (name) {
    if (!decks[name]) {
      decks[name] = [];
      currentDeckKey = name;
      saveStorage();
      populateDeckSelect();
      renderCard();
    }
    closeModal('newDeckModal');
  }
}

function closeModal(id) {
  document.getElementById(id).classList.remove('open');
}

populateDeckSelect();
renderCard();
